from flask import Flask, request
import sqlite3
from pathlib import Path
app = Flask(__name__)
@app.get('/search')
def search():
    db = sqlite3.connect('/data/app.db')
    return {'rows': db.execute("SELECT name FROM people WHERE name = '" + request.args['q'] + "'").fetchall()}
@app.post('/upload')
def upload():
    file = request.files['file']
    file.save(Path('/data/uploads') / file.filename)
    return {'ok': True}

