def download(actor, document_id, store):
    if actor is None:
        return 401, None
    if not isinstance(document_id, int) or isinstance(document_id, bool) or document_id <= 0:
        return 400, None
    row = store.find(document_id, actor.id, actor.tenant_id)
    return (404, None) if row is None else (200, row.bytes)
